CREATE TABLE `balance_patches` (
	`id` text PRIMARY KEY NOT NULL,
	`applied_at` text NOT NULL,
	`post_id` text,
	`title_json` text NOT NULL,
	`items_json` text NOT NULL,
	`changes_json` text,
	`created_at` text NOT NULL
);
--> statement-breakpoint
CREATE INDEX `balance_patches_applied_idx` ON `balance_patches` (`applied_at`);--> statement-breakpoint
/* T-11-333 시즌 1(2026-10-09~10-14)에 코드 배포로 나간 밸런스 패치를 공개 이력에 채운다. 적용 시각·글 id는 그 패치를 알린
   릴리즈 노트의 운영 게시 기록(app_meta release-note:<id>) 그대로다. 이후 패치는 릴리즈 노트의 balance 표시로 자동 쌓인다. */
INSERT OR IGNORE INTO balance_patches (id, applied_at, post_id, title_json, items_json, changes_json, created_at) VALUES
  ('t-11-168-midfield-legend', '2026-10-09T07:07:53.731Z', 'pst_release_20261009', '{"ko":"미드필더 레전드 점수 조정","en":"Midfielder legend score rebalance","ja":"MFのレジェンドスコア調整"}', '{"ko":["공격형 미드필더는 경기 장악 점수를 받지 않아요. 골과 도움으로 공격수만큼 점수를 쌓아 상위권을 독차지했어요.","중앙 미드필더의 경기 장악 점수를 줄였어요. 수비형 미드필더는 그대로예요.","이미 은퇴한 선수의 레전드 점수도 새 기준으로 다시 매겨 명예의 전당 순위에 반영했어요."],"en":["Attacking midfielders no longer earn game control points. Their goals and assists already add up like a forward''s, so they were taking over the top of the rankings.","Central midfielders now earn fewer game control points. Defensive midfielders stay the same.","Legend scores of players who already retired were recalculated too, and the Hall of Fame rankings reflect the new scores."],"ja":["攻撃的MFは試合支配ポイントを受け取らなくなります。ゴールとアシストでFW並みにスコアを積み、上位を独占していました。","セントラルMFの試合支配ポイントを減らしました。守備的MFは変わりません。","すでに引退した選手のレジェンドスコアも新しい基準で計算し直し、殿堂の順位に反映しました。"]}', NULL, '2026-10-17T09:30:00.000Z'),
  ('t-11-172-boost-no-day-cap', '2026-10-09T08:30:06.547Z', 'pst_release_20261009', '{"ko":"광고 강화 하루 횟수 제한 해제","en":"No daily limit on ad boosts","ja":"広告強化の1日回数制限を解除"}', '{"ko":["광고로 받는 잠재력 강화에 하루 횟수 제한이 없어졌어요.","추가 시도는 지금처럼 선수마다 2번까지예요."],"en":["Potential boosts from ads no longer have a daily limit.","Extra tries are still up to 2 per player."],"ja":["広告で受けるポテンシャル強化に1日の回数制限がなくなりました。","追加挑戦はこれまでどおり選手ごとに2回までです。"]}', NULL, '2026-10-17T09:30:00.000Z'),
  ('t-11-173-club-boost-no-cap', '2026-10-09T09:43:16.017Z', 'pst_release_20261009', '{"ko":"구단 자금 강화 하루 횟수 제한 해제","en":"No daily limit on club-funds boosts","ja":"クラブ資金強化の1日回数制限を解除"}', '{"ko":["구단 자금으로 받는 잠재력 강화에도 하루 횟수 제한이 없어졌어요.","같은 날 다시 받을수록 구단 자금 값은 지금처럼 올라요."],"en":["Potential boosts with club funds no longer have a daily limit.","The club-funds price still rises each time you buy on the same day."],"ja":["クラブ資金で受けるポテンシャル強化にも1日の回数制限がなくなりました。","同じ日にもう一度受けるほど、クラブ資金の値段はこれまでどおり上がります。"]}', NULL, '2026-10-17T09:30:00.000Z'),
  ('t-11-196-premium-scout', '2026-10-10T18:02:42.033Z', 'pst_release_20261011', '{"ko":"프리미엄 스카우트권","en":"Premium scout tickets","ja":"プレミアムスカウト券"}', '{"ko":["프리미엄 스카우트권으로 후보 3명을 새로 뽑으면 1명은 잠재력 A 이상이 보장돼요.","모든 후보가 S일 확률은 일반 스카우트의 2배이고, 등급별 확률은 확률 보기에서 공개해요."],"en":["Draw 3 new candidates with a premium scout ticket, and one of them is guaranteed potential A or higher.","Every candidate''s chance of S is twice that of a regular scout. Odds by grade are shown under Show odds."],"ja":["プレミアムスカウト券で候補3人を新しく選ぶと、1人はポテンシャルA以上が保証されます。","すべての候補がSになる確率は通常スカウトの2倍で、等級別の確率は「確率を見る」で公開しています。"]}', NULL, '2026-10-17T09:30:00.000Z'),
  ('t-11-197-team-slot-synergy', '2026-10-11T02:16:25.915Z', 'pst_release_20261011', '{"ko":"구단주 팀 자리 실력 · 시너지 상한 해제","en":"Owner team: position ratings and no synergy cap","ja":"オーナーチームのポジション能力・シナジー上限の撤廃"}', '{"ko":["팀 시너지 효과 상한을 없앴어요. 켜진 시너지는 모두 경기에 더해져요.","주 포지션보다 다른 자리가 더 잘 맞는 선수는 그 자리에서 최고 OVR보다 2까지 더 높게 뛰어요. 이후 은퇴하는 선수부터 적용돼요."],"en":["Team synergies no longer have a cap. Every active synergy adds to your matches.","Players who suit another position better than their main one can play up to 2 above their peak OVR there. This applies to players who retire from then on."],"ja":["チームシナジーの効果上限をなくしました。有効なシナジーはすべて試合に加わります。","本来のポジションより別のポジションが合う選手は、そこで最高OVRより最大2高くプレーします。以後に引退する選手から適用されます。"]}', NULL, '2026-10-17T09:30:00.000Z'),
  ('t-11-224-lounge-fixes', '2026-10-12T14:13:52.371Z', 'pst_release_20261012', '{"ko":"이벤트 선택 결과가 성공 · 실패와 어긋나지 않게 고쳤어요","en":"Event outcomes now match success and failure","ja":"イベントの結果が成功・失敗と食い違わないよう修正しました"}', '{"ko":["이벤트에서 성공했는데 능력치가 깎이거나 실패했는데 능력치가 오르는 일이 없어졌어요.","고교 · 대학에서 OVR이 높으면 그 수준에 맞는 구단에서 제의가 와요."],"en":["Events no longer lower an attribute after a success or raise one after a failure.","High-rated school and university players now get offers from clubs that match their level."],"ja":["イベントで成功したのに能力値が下がったり、失敗したのに上がったりすることがなくなりました。","高校・大学でOVRが高いと、そのレベルに合ったクラブからオファーが届きます。"]}', NULL, '2026-10-17T09:30:00.000Z'),
  ('t-11-229-growth-targetman', '2026-10-12T16:28:05.431Z', 'pst_release_20261013', '{"ko":"타겟맨 훈련과 잠재력 근처 성장이 좋아졌어요","en":"Better growth for target men and players near their potential","ja":"ターゲットマンと潜在能力付近の成長が良くなりました"}', '{"ko":["타겟맨은 헤딩·몸싸움·점프로 키워도 OVR이 올라요.","스트라이커처럼 키운 타겟맨도 OVR이 내려가지 않아요.","OVR이 잠재력에 닿은 뒤에도 훈련하면 조금씩 더 자라요."],"en":["Target men now gain OVR when you train heading, strength and jumping.","Target men built like strikers do not lose any OVR.","Players keep growing a little with training even after OVR reaches potential."],"ja":["ターゲットマンはヘディング・フィジカル・ジャンプを鍛えてもOVRが上がります。","ストライカーのように育てたターゲットマンもOVRは下がりません。","OVRが潜在能力に届いた後も、トレーニングで少しずつ成長します。"]}', '[{"key":"potGrowthFloor","from":0.04,"to":0.15},{"key":"targetManRole","from":0,"to":1}]', '2026-10-17T09:30:00.000Z'),
  ('t-11-236-fans-targetman-winger', '2026-10-13T05:57:51.766Z', 'pst_release_20261013', '{"ko":"타겟맨·윙어 OVR을 고쳤어요","en":"Target man and winger OVR fixes","ja":"ターゲットマン・ウインガーのOVRを修正しました"}', '{"ko":["타겟맨이 스트라이커 자리에서도 카드 OVR 그대로 뛰어요.","윙어 유형 측면 미드필더는 스피드를 키워도 OVR이 올라요."],"en":["Target men now play at their card OVR in the striker slot.","Winger-type wide midfielders now gain OVR from pace."],"ja":["ターゲットマンがストライカーの位置でもカードのOVRどおりにプレーします。","ウインガー型のサイドMFはスピードを伸ばしてもOVRが上がります。"]}', NULL, '2026-10-17T09:30:00.000Z'),
  ('t-11-244-scout-pity', '2026-10-13T15:31:26.375Z', 'pst_release_20261014', '{"ko":"프리미엄 스카우트 천장","en":"Premium scout pity","ja":"プレミアムスカウトの天井"}', '{"ko":["프리미엄 스카우트권을 S 후보 없이 29장 쓰면 30장째는 S 후보가 확정돼요. 누적 100장째마다 잠재력 최고치 S 후보가 나와요.","지금까지 쓴 프리미엄 스카우트권도 누적 장수에 들어가요. 남은 장수는 후보 선택 화면에 보여요."],"en":["If 29 premium scout tickets in a row bring no S candidate, the 30th guarantees one. Every 100th ticket brings an S candidate with top potential.","Premium scout tickets you have already used count toward the total. The candidate screen shows how many are left."],"ja":["S候補なしでプレミアムスカウト券を29枚使うと、30枚目でS候補が確定します。累計100枚目ごとにポテンシャル最高値のS候補が出ます。","これまで使ったプレミアムスカウト券も累計に含まれます。残り枚数は候補選択画面に表示されます。"]}', NULL, '2026-10-17T09:30:00.000Z');